def human_bytes(n: int) -> str:
    if n < 0:
        raise ValueError("size must be non-negative")
    units = ["B", "KiB", "MiB", "GiB", "TiB"]
    i = 0
    while i < len(units) - 1 and n >= 1024 ** (i + 1):
        i += 1
    if i == 0:
        return f"{n} B"
    value = n / 1024 ** i
    return f"{value:.1f} {units[i]}"

