def split_model_ref(ref: str) -> tuple[str, str]:
    ref = ref.strip()
    slash = ref.rfind("/")
    colon = ref.rfind(":")
    if colon > slash:
        name, tag = ref[:colon], ref[colon + 1:]
    else:
        name, tag = ref, "latest"
    if not name or not tag:
        raise ValueError(f"bad model reference: {ref!r}")
    return name, tag

def free_ports(used, start: int, count: int) -> list[int]:
    if not 1 <= start <= 65535:
        raise ValueError("start out of range")
    if count < 0:
        raise ValueError("count must be non-negative")
    taken = set(used)
    out: list[int] = []
    port = start
    while len(out) < count and port <= 65535:
        if port not in taken:
            out.append(port)
        port += 1
    if len(out) < count:
        raise ValueError("not enough free ports")
    return out

