import re
from fractions import Fraction

_SIZE = re.compile(r"\s*(\d+(?:\.\d+)?)\s*([A-Za-z]*)\s*")
_MULT = {
    "": 1, "B": 1,
    "KB": 1000, "MB": 1000**2, "GB": 1000**3, "TB": 1000**4,
    "KiB": 1024, "MiB": 1024**2, "GiB": 1024**3, "TiB": 1024**4,
    "K": 1024, "M": 1024**2, "G": 1024**3, "T": 1024**4,
}


def parse_size(text: str) -> int:
    m = _SIZE.fullmatch(text)
    if not m or m.group(2) not in _MULT:
        raise ValueError(f"bad size: {text!r}")
    return int(Fraction(m.group(1)) * _MULT[m.group(2)])

def merge_windows(windows: list[tuple[int, int]]) -> list[tuple[int, int]]:
    for start, end in windows:
        if start > end:
            raise ValueError(f"window ends before it starts: {(start, end)}")
    merged: list[list[int]] = []
    for start, end in sorted(w for w in windows if w[0] < w[1]):
        if merged and start <= merged[-1][1]:
            merged[-1][1] = max(merged[-1][1], end)
        else:
            merged.append([start, end])
    return [(s, e) for s, e in merged]

from collections import deque


def hops(links: list[tuple[str, str]], src: str, dst: str) -> int | None:
    if src == dst:
        return 0
    adj: dict[str, set[str]] = {}
    for a, b in links:
        adj.setdefault(a, set()).add(b)
        adj.setdefault(b, set()).add(a)
    if src not in adj or dst not in adj:
        return None
    seen = {src}
    queue = deque([(src, 0)])
    while queue:
        node, dist = queue.popleft()
        for nxt in adj[node]:
            if nxt == dst:
                return dist + 1
            if nxt not in seen:
                seen.add(nxt)
                queue.append((nxt, dist + 1))
    return None

def render_table(rows: list[dict], columns: list[str]) -> str:
    def text(v):
        if v is None:
            return "-"
        if isinstance(v, float):
            return f"{v:.1f}"
        return str(v)

    def numeric(v):
        return isinstance(v, (int, float)) and not isinstance(v, bool)

    cells = [[(text(r.get(c)), numeric(r.get(c))) for c in columns] for r in rows]
    widths = [max([len(c)] + [len(row[i][0]) for row in cells]) for i, c in enumerate(columns)]
    lines = ["  ".join(c.ljust(w) for c, w in zip(columns, widths)).rstrip(),
             "  ".join("-" * w for w in widths)]
    for row in cells:
        parts = [t.rjust(w) if num else t.ljust(w) for (t, num), w in zip(row, widths)]
        lines.append("  ".join(parts).rstrip())
    return "\n".join(lines)

import re

_PAIR = re.compile(r'([A-Za-z_][A-Za-z0-9_]*)=(?:"([^"]*)"|([^\s"]+))(?=\s|$)')
_DIGITS = re.compile(r"[0-9]+")


def parse_access_log(line: str) -> dict | None:
    line = line.strip()
    if not line:
        return None
    parts = line.split(None, 1)
    ts = parts[0]
    if "=" in ts:
        return None
    rest = parts[1] if len(parts) > 1 else ""
    fields: dict[str, str] = {}
    pos = 0
    while True:
        while pos < len(rest) and rest[pos].isspace():
            pos += 1
        if pos >= len(rest):
            break
        m = _PAIR.match(rest, pos)
        if not m:
            return None
        fields[m.group(1)] = m.group(2) if m.group(2) is not None else m.group(3)
        pos = m.end()
    out: dict = {"ts": ts}
    if "model" not in fields:
        return None
    out["model"] = fields["model"]
    for key in ("status", "latency_ms", "tokens"):
        value = fields.get(key)
        if value is None or not _DIGITS.fullmatch(value):
            return None
        out[key] = int(value)
    return out

def budget_alerts(limit: float, charges: list[float], thresholds: tuple[float, ...] = (0.5, 0.8, 1.0)) -> list[tuple[int, float]]:
    if limit <= 0:
        raise ValueError("limit must be positive")
    if any(c < 0 for c in charges):
        raise ValueError("charges must be non-negative")
    pending = sorted(thresholds)
    fired: list[tuple[int, float]] = []
    total = 0.0
    for i, charge in enumerate(charges):
        total += charge
        while pending and total >= pending[0] * limit:
            fired.append((i, pending.pop(0)))
    return fired

