def place_models(models: dict[str, int], gpus: dict[str, int]) -> dict[str, str]:
    free = dict(gpus)
    out: dict[str, str] = {}
    for name, size in sorted(models.items(), key=lambda kv: (-kv[1], kv[0])):
        if not free:
            raise ValueError(f"no GPU for {name}")
        gpu = min(free, key=lambda g: (-free[g], g))
        if free[gpu] < size:
            raise ValueError(f"{name} does not fit on any GPU")
        free[gpu] -= size
        out[name] = gpu
    return out

