from collections import deque


def admit(times: list[float], limit: int, window: float) -> list[bool]:
    if limit < 1:
        raise ValueError("limit must be >= 1")
    if window <= 0:
        raise ValueError("window must be positive")
    for a, b in zip(times, times[1:]):
        if b < a:
            raise ValueError("times must be non-decreasing")
    admitted: deque[float] = deque()
    out: list[bool] = []
    for t in times:
        while admitted and admitted[0] <= t - window:
            admitted.popleft()
        if len(admitted) < limit:
            admitted.append(t)
            out.append(True)
        else:
            out.append(False)
    return out

def parse_quadlet(text: str) -> dict[str, dict[str, list[str]]]:
    result: dict[str, dict[str, list[str]]] = {}
    section: str | None = None
    lines = text.splitlines()
    i = 0
    while i < len(lines):
        line = lines[i].strip()
        i += 1
        if not line or line[0] in "#;":
            continue
        while line.endswith("\\"):
            if i >= len(lines):
                raise ValueError("continuation on the last line")
            line = (line[:-1].strip() + " " + lines[i].strip()).strip()
            i += 1
        if line.startswith("[") and line.endswith("]"):
            section = line[1:-1].strip()
            result.setdefault(section, {})
            continue
        if section is None:
            raise ValueError(f"key outside a section: {line!r}")
        if "=" not in line:
            raise ValueError(f"not a key=value line: {line!r}")
        key, _, value = line.partition("=")
        result[section].setdefault(key.strip(), []).append(value.strip())
    return result

import re

_TOKEN = re.compile(r"\s*(?:(\d+(?:\.\d+)?)|([A-Za-z_][A-Za-z0-9_]*)|([-+*/()]))")


def evaluate(expr: str, env: dict[str, float]) -> float:
    tokens: list[tuple[str, str]] = []
    pos = 0
    while pos < len(expr):
        if expr[pos:].strip() == "":
            break
        m = _TOKEN.match(expr, pos)
        if not m:
            raise ValueError(f"unexpected character at {pos}")
        if m.group(1) is not None:
            if m.end() < len(expr) and (expr[m.end()] == "." or expr[m.end()].isalpha() or expr[m.end()] == "_"):
                raise ValueError("malformed number")
            tokens.append(("num", m.group(1)))
        elif m.group(2) is not None:
            tokens.append(("name", m.group(2)))
        else:
            tokens.append(("op", m.group(3)))
        pos = m.end()
    i = 0

    def peek():
        return tokens[i] if i < len(tokens) else (None, None)

    def take():
        nonlocal i
        tok = peek()
        i += 1
        return tok

    def expression() -> float:
        value = term()
        while peek() in (("op", "+"), ("op", "-")):
            _, op = take()
            rhs = term()
            value = value + rhs if op == "+" else value - rhs
        return value

    def term() -> float:
        value = unary()
        while peek() in (("op", "*"), ("op", "/")):
            _, op = take()
            rhs = unary()
            if op == "*":
                value *= rhs
            else:
                if rhs == 0:
                    raise ZeroDivisionError("division by zero")
                value /= rhs
        return value

    def unary() -> float:
        if peek() == ("op", "-"):
            take()
            return -unary()
        if peek() == ("op", "+"):
            take()
            return unary()
        return primary()

    def primary() -> float:
        kind, val = take()
        if kind == "num":
            return float(val)
        if kind == "name":
            return float(env[val])
        if (kind, val) == ("op", "("):
            value = expression()
            if take() != ("op", ")"):
                raise ValueError("missing )")
            return value
        raise ValueError(f"unexpected token {val!r}")

    if not tokens:
        raise ValueError("empty expression")
    result = expression()
    if i != len(tokens):
        raise ValueError("trailing tokens")
    return float(result)

from datetime import datetime, timezone
from zoneinfo import ZoneInfo


def merge_local_windows(windows: list[tuple[str, str, str]]) -> list[tuple[str, str]]:
    spans = []
    for start, end, tz in windows:
        zone = ZoneInfo(tz)
        s = datetime.strptime(start, "%Y-%m-%d %H:%M").replace(tzinfo=zone).astimezone(timezone.utc)
        e = datetime.strptime(end, "%Y-%m-%d %H:%M").replace(tzinfo=zone).astimezone(timezone.utc)
        if e <= s:
            raise ValueError(f"window ends before it starts: {(start, end, tz)}")
        spans.append((s, e))
    spans.sort()
    merged: list[list[datetime]] = []
    for s, e in spans:
        if merged and s <= merged[-1][1]:
            merged[-1][1] = max(merged[-1][1], e)
        else:
            merged.append([s, e])
    fmt = "%Y-%m-%dT%H:%MZ"
    return [(s.strftime(fmt), e.strftime(fmt)) for s, e in merged]

import time
from collections import OrderedDict


class TTLCache:
    def __init__(self, capacity: int, ttl: float, clock=time.monotonic):
        if capacity < 1:
            raise ValueError("capacity must be >= 1")
        if ttl <= 0:
            raise ValueError("ttl must be positive")
        self.capacity = capacity
        self.ttl = ttl
        self.clock = clock
        self._data: OrderedDict = OrderedDict()

    def _expired(self, key, now: float) -> bool:
        return now >= self._data[key][1]

    def get(self, key, default=None):
        if key not in self._data:
            return default
        now = self.clock()
        if self._expired(key, now):
            del self._data[key]
            return default
        self._data.move_to_end(key)
        return self._data[key][0]

    def set(self, key, value) -> None:
        now = self.clock()
        if key not in self._data and len(self._data) >= self.capacity:
            for k in [k for k in self._data if self._expired(k, now)]:
                del self._data[k]
            if len(self._data) >= self.capacity:
                self._data.popitem(last=False)
        self._data[key] = (value, now + self.ttl)
        self._data.move_to_end(key)

    def __len__(self) -> int:
        now = self.clock()
        return sum(1 for k in self._data if not self._expired(k, now))

import re

_VER = re.compile(r"v?(\d+)\.(\d+)\.(\d+)")
_CMP = re.compile(r"(>=|<=|==|!=|>|<|\^|~)\s*(\S+)")


def _parse(v: str) -> tuple[int, int, int]:
    m = _VER.fullmatch(v.strip())
    if not m:
        raise ValueError(f"bad version: {v!r}")
    return tuple(int(x) for x in m.groups())  # type: ignore[return-value]


def _check(ver: tuple[int, int, int], comparator: str) -> bool:
    comparator = comparator.strip()
    if not comparator:
        raise ValueError("empty comparator")
    if comparator == "*":
        return True
    m = _CMP.fullmatch(comparator)
    if not m:
        raise ValueError(f"bad comparator: {comparator!r}")
    op, target = m.group(1), _parse(m.group(2))
    if op == ">=":
        return ver >= target
    if op == "<=":
        return ver <= target
    if op == ">":
        return ver > target
    if op == "<":
        return ver < target
    if op == "==":
        return ver == target
    if op == "!=":
        return ver != target
    major, minor, patch = target
    if op == "~":
        upper = (major, minor + 1, 0)
    elif major > 0:
        upper = (major + 1, 0, 0)
    elif minor > 0:
        upper = (0, minor + 1, 0)
    else:
        upper = (0, 0, patch + 1)
    return target <= ver < upper


def satisfies(version: str, spec: str) -> bool:
    ver = _parse(version)
    if not spec.strip():
        raise ValueError("empty spec")
    results = []
    for alternative in spec.split("||"):
        if not alternative.strip():
            raise ValueError("empty alternative")
        results.append(all([_check(ver, c) for c in alternative.split(",")]))
    return any(results)

def schedule(weights: dict[str, int], n: int) -> list[str]:
    if any(w < 0 for w in weights.values()):
        raise ValueError("weights must be non-negative")
    if n < 0:
        raise ValueError("n must be non-negative")
    total = sum(weights.values())
    if n > 0 and total == 0:
        raise ValueError("no backend has a positive weight")
    current = {name: 0 for name in weights}
    picks: list[str] = []
    for _ in range(n):
        best = None
        for name, w in weights.items():
            current[name] += w
            if best is None or current[name] > current[best]:
                best = name
        current[best] -= total
        picks.append(best)
    return picks
